text:
{
  "title_novice": "Глубокое проникновение в карбонатных коллекторах",
  "summary": [
    {"text": "В карбонатных межзерновых коллекторах фильтрат бурового раствора проникает в пласт глубже, чем в терригенных.", "claims": ["c1"]},
    {"text": "Из-за этого сопротивление неизменённой части пласта (ρн) может быть сопоставимым у продуктивного коллектора и неколлектора.", "claims": ["c3"]},
    {"text": "Поэтому метод собственных потенциалов (СП) и гамма-метод (ГМ) слабо связаны с коллекторскими свойствами, и оценка насыщения затрудняется.", "claims": ["c5", "c6"]}
  ],
  "claims": [
    {"key": "c1", "text": "В карбонатных межзерновых коллекторах фильтрат проникает глубже, чем в терригенных; автор называет это первой особенностью карбонатного разреза.", "kind": "observation", "unit_id": "u-105-acb61e", "page": 105, "quote": "обусловливает формирование в карбонатных межзерновых коллекторах более глубокого по сравнению с терригенными проникновения фильтрата промывочной жидкости", "numbers": [], "question": null},
    {"key": "c2", "text": "При уменьшении пористости глубина проникновения растёт; условие: при прочих равных и до некоторого предела.", "kind": "observation", "unit_id": "u-105-acb61e", "page": 105, "quote": "с уменьшением пористости (до некоторого предела) глубина проникновения в коллекторы при прочих равных условиях растет", "numbers": [], "question": null},
    {"key": "c3", "text": "Из-за глубокого проникновения значения ρн в продуктивном коллекторе и неколлекторе становятся сопоставимыми.", "kind": "inference", "unit_id": "u-105-acb61e", "page": 105, "quote": "Эта же особенность — причина соизмеримости значений", "numbers": [], "question": null},
    {"key": "c4", "text": "Структура порового пространства и широкий диапазон изменений тоже затрудняют оценку насыщения; автор ссылается на обстоятельства, перечисленные выше.", "kind": "inference", "unit_id": "u-107-9751d2", "page": 107, "quote": "Эти обстоятельства и влияние структуры порового пространства, а также широкий диапазон изменений", "numbers": [], "question": null},
    {"key": "c5", "text": "Отсутствие корреляции коллекторских свойств с глинистостью снижает эффективность СП и ГМ при изучении межзерновых коллекторов в карбонатах.", "kind": "inference", "unit_id": "u-107-9751d2", "page": 107, "quote": "Отсутствие корреляции коллекторских свойств с глинистостью снижает эффективность методов СП и ГМ при изучении межзерновых коллекторов в карбонатном разрезе.", "numbers": [], "question": null},
    {"key": "c6", "text": "Эти обстоятельства существенно затрудняют определение характера насыщения коллектора.", "kind": "inference", "unit_id": "u-107-9751d2", "page": 107, "quote": "существенно затрудняют оценку характера насыщения коллектора", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Фильтрат бурового раствора уходит в поры проницаемого пласта; в карбонатных межзерновых коллекторах он проникает глубже, чем в терригенных.", "claims": ["c1"], "hypothesis": false},
    {"text": "Глубина проникновения растёт, когда пористость падает, при прочих равных условиях и до некоторого предела.", "claims": ["c2"], "hypothesis": false},
    {"text": "Из-за глубокого проникновения значения удельного сопротивления неизменённой части пласта (ρн) в продуктивном коллекторе и неколлекторе становятся сопоставимыми.", "claims": ["c3"], "hypothesis": false},
    {"text": "Почему это так, вероятно: зонд в основном видит зону проникновения, заполненную фильтратом, а не нетронутую часть пласта.", "claims": [], "hypothesis": true},
    {"text": "Слабость СП и ГМ, вероятно, связана с тем, что их отклик отражает глинистость, а в карбонатах глинистость слабо связана с коллекторскими свойствами.", "claims": ["c5"], "hypothesis": true}
  ],
  "practice": [
    {"text": "В карбонатном разрезе не делают вывод о нефти только по высокому сопротивлению; сначала оценивают глубину проникновения фильтрата.", "claims": [], "hypothesis": true},
    {"text": "Метод СП и гамма-метод в таких коллекторах рассматривают как слабый признак, а не как основной.", "claims": [], "hypothesis": true},
    {"text": "Если сопротивления продуктивного и водоносного пласта сопоставимы, переходят к методам, учитывающим проникновение (нормализация, узел n64).", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Связь пористости и глубины проникновения действует только до некоторого предела; сам предел в тексте не назван.", "claims": ["c2"], "hypothesis": false},
    {"text": "Структура порового пространства и широкий диапазон изменений тоже затрудняют оценку насыщения; автор ссылается на особенности, перечисленные выше.", "claims": ["c4"], "hypothesis": false},
    {"text": "Слабая связь СП и ГМ с глинистостью касается именно межзерновых коллекторов в карбонатном разрезе.", "claims": ["c5"], "hypothesis": false},
    {"text": "Соизмеримость означает сопоставимость значений, а не их равенство.", "claims": [], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Почему нельзя сравнить два сопротивления и решить", "text": "Если значения близки, по одному показанию не различить нефть и воду; нужен второй признак, например пористость или нормализация (узел n64).", "claims": [], "hypothesis": true},
    {"title": "Что говорит глава о механизме", "text": "В этом фрагменте глава описывает связь, но не объясняет физику. Для объяснения нужна физика пор и фильтрации.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Условие: при прочих равных условиях глубина проникновения растёт с уменьшением пористости.", "claims": ["c2"]},
    {"text": "Граница действия: зависимость верна до некоторого предела пористости; значение предела в тексте не названо.", "claims": ["c2"]},
    {"text": "Соизмеримость ρн наблюдается в карбонатных межзерновых коллекторах, где фильтрат проникает глубоко.", "claims": ["c3"]}
  ],
